    const { id } = await params;
    const customer = await db.customer.findUnique({
      where: { id },
      include: {
        ga: true,
        devices: {
          include: {
            alarms: {
              where: { status: "OPEN" },
            },
            readings: {
              orderBy: { readingDate: "desc" },
              take: 1,
