                      </TableCell>
                    </TableRow>
                  ) : devices.length === 0 ? (
                    <TableRow className="border-slate-200 dark:border-slate-800">
                      <TableCell colSpan={2} className="text-center py-6 text-slate-500 dark:text-slate-400 text-sm">
                        No meters found.
                      </TableCell>
                    </TableRow>
                  ) : (
                    devices.map((d) => (
                      <TableRow 
